SP0 = 1.00;  SP1 = 1.30;  SP2 = 1.60;

%% ── Step times & metrics (pre-computed) ─────────────────────────────────────
t_step1 = 5.0;   t_step2 = 14.0;
os1_pct = 6.3333;  rise1 = 1.4950;  settle1 = 4.7600;  ss1_rmse = 0.6235;
os2_pct = 7.3000;  rise2 = 1.4600;  settle2 = 4.0200;  ss2_rmse = 0.3007;

%% ── 2nd-order reference ──────────────────────────────────────────────────────
os1_frac = max(0.001, min(os1_pct/100, 0.999));
zeta = -log(os1_frac) / sqrt(pi^2 + log(os1_frac)^2);
wn   = (1 - 0.4167*zeta + 2.917*zeta^2) / rise1;
wd   = wn * sqrt(max(0, 1 - zeta^2));
phi  = acos(max(-1, min(1, zeta)));

mask1 = T >= t_step1 & T < t_step2;
mask2 = T >= t_step2;
z_ref = zeros(size(T));
z_ref(T < t_step1) = SP0;
tr1 = T(mask1) - t_step1;
z_ref(mask1) = SP0 + (SP1-SP0) * (1 - exp(-zeta*wn*tr1)./sqrt(1-zeta^2).*sin(wd*tr1+phi));
tr2 = T(mask2) - t_step2;
z_ref(mask2) = SP1 + (SP2-SP1) * (1 - exp(-zeta*wn*tr2)./sqrt(1-zeta^2).*sin(wd*tr2+phi));

err_cm = abs(z_ekf - z_sp) * 100;

%% ── Colours ──────────────────────────────────────────────────────────────────
cTrue = [0.20 0.45 0.85];  cEKF = [0.25 0.72 0.38];
cSP   = [0.85 0.18 0.18];  cRef = [0.55 0.15 0.75];

%% ── Figure ───────────────────────────────────────────────────────────────────
fig = figure('Name','B1 — Altitude hold','Position',[60 60 1120 720]);
LFT=0.10; WID=0.82; BOT_LO=0.09; HGT_LO=0.24; GAP=0.10;
BOT_UP=BOT_LO+HGT_LO+GAP; HGT_UP=0.48;

ax1 = axes('Position',[LFT BOT_UP WID HGT_UP]);
hold on;
plot(ax1, T, z_true, '-',  'Color',cTrue, 'LineWidth',1.5, 'DisplayName','True altitude (sim)');
plot(ax1, T, z_ekf,  '-',  'Color',cEKF,  'LineWidth',1.5, 'DisplayName','EKF estimate');
stairs(ax1,  T, z_sp, '--', 'Color',cSP,  'LineWidth',1.5, 'DisplayName','Setpoint');
plot(ax1, T, z_ref,  ':',  'Color',cRef,  'LineWidth',1.4, ...
     'DisplayName', sprintf('2nd-order ref (\zeta=%.2f, \omega_n=%.2f rad/s) [Ref 1]', zeta, wn));
xline(ax1, t_step1, ':', 'Color',[.5 .5 .5], 'LineWidth',1.0, 'HandleVisibility','off');
xline(ax1, t_step2, ':', 'Color',[.5 .5 .5], 'LineWidth',1.0, 'HandleVisibility','off');
patch(ax1, [0 T(end) T(end) 0], [SP1-.015 SP1-.015 SP1+.015 SP1+.015], ...
      [0 .8 0], 'FaceAlpha',.10, 'EdgeColor','none', 'HandleVisibility','off');
patch(ax1, [0 T(end) T(end) 0], [SP2-.015 SP2-.015 SP2+.015 SP2+.015], ...
      [0 .8 0], 'FaceAlpha',.10, 'EdgeColor','none', 'HandleVisibility','off');
text(ax1, t_step1+0.3, SP1+0.08, ...
     sprintf('OS=%.2f%%\nRise=%.3fs\nSettle=%.3fs\nSS=%.2fcm', os1_pct,rise1,settle1,ss1_rmse), ...
     'FontSize',16, 'BackgroundColor',[1 1 .88], 'EdgeColor',[.7 .7 .5], 'Margin',3);
text(ax1, t_step2+3.0, SP2-0.28, ...
     sprintf('OS=%.2f%%\nRise=%.3fs\nSettle=%.3fs\nSS=%.2fcm', os2_pct,rise2,settle2,ss2_rmse), ...
     'FontSize',16, 'BackgroundColor',[1 1 .88], 'EdgeColor',[.7 .7 .5], 'Margin',3);
set(ax1,'XLim',[0 T(end)],'YLim',[0.93 1.72],'Box','off', ...
        'YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--','XTickLabel',{});
ylabel(ax1,'Altitude  (m)','FontSize',25);
title(ax1, {'EXP-B1: Altitude Hold Step Response  (1.0 m \rightarrow 1.3 m \rightarrow 1.6 m)'; ...
            'Literature benchmark: rise 1-2 s, overshoot \leq10%, SS <2 cm [Ref 2, 4]'}, 'FontSize',25);
legend(ax1, 'FontSize',16, 'Location','northwest', 'Box','off');
hold off;

ax2 = axes('Position',[LFT BOT_LO WID HGT_LO]);
hold on;
plot(ax2, T, err_cm, '-', 'Color',cRef, 'LineWidth',1.0, 'DisplayName','|EKF error|  (cm)');
yline(ax2, 5.0, '--', 'Color','red', 'LineWidth',1.0, 'DisplayName','5 cm band');
xline(ax2, t_step1, ':', 'Color',[.5 .5 .5], 'LineWidth',1.0, 'HandleVisibility','off');
xline(ax2, t_step2, ':', 'Color',[.5 .5 .5], 'LineWidth',1.0, 'HandleVisibility','off');
set(ax2,'XLim',[0 T(end)],'Box','off', ...
        'YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax2,'Time  (s)','FontSize',25);
ylabel(ax2,'Altitude error  (cm)','FontSize',25);
legend(ax2, 'FontSize',16, 'Location','northeast', 'Box','off');
hold off;

linkaxes([ax1 ax2], 'x');
